import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float sigmoidf_(float v) {
  return 1.0f / (1.0f + __expf(-v));
}

// Elementwise sigmoid kernel written with CuTe tensors/layouts.
// Each thread processes Vec contiguous elements in a vectorized fashion.
template <int Vec>
__global__ void sigmoid_kernel_vec(const float* __restrict__ X,
                                   float* __restrict__ Y,
                                   int64_t numel_vec)
{
  // Unrolled vectorized kernel: each thread processes Unroll independent
  // float4 vectors per outer iteration. Issuing multiple independent
  // 128-bit loads before consuming them increases memory-level
  // parallelism (ILP/MLP), which helps saturate DRAM bandwidth on this
  // memory-bound elementwise op while keeping every load/store coalesced.
  constexpr int Unroll = 4;
  const float4* Xv = reinterpret_cast<const float4*>(X);
  float4* Yv = reinterpret_cast<float4*>(Y);
  Tensor mX = make_tensor(make_gmem_ptr(Xv), make_shape(numel_vec));
  Tensor mY = make_tensor(make_gmem_ptr(Yv), make_shape(numel_vec));
  const int64_t chunk = (int64_t)blockDim.x * Unroll;
  const int64_t step = (int64_t)gridDim.x * chunk;
  for (int64_t base = (int64_t)blockIdx.x * chunk; base < numel_vec; base += step) {
    const int64_t i0 = base + threadIdx.x;
    float4 v[Unroll];
#pragma unroll
    for (int u = 0; u < Unroll; ++u) {
      const int64_t i = i0 + (int64_t)u * blockDim.x;
      if (i < numel_vec) v[u] = mX(i);
    }
#pragma unroll
    for (int u = 0; u < Unroll; ++u) {
      v[u].x = sigmoidf_(v[u].x);
      v[u].y = sigmoidf_(v[u].y);
      v[u].z = sigmoidf_(v[u].z);
      v[u].w = sigmoidf_(v[u].w);
    }
#pragma unroll
    for (int u = 0; u < Unroll; ++u) {
      const int64_t i = i0 + (int64_t)u * blockDim.x;
      if (i < numel_vec) mY(i) = v[u];
    }
  }
}

// Scalar tail kernel for leftover elements not covered by vector kernel.
__global__ void sigmoid_kernel_tail(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int64_t offset,
                                    int64_t tail)
{
  int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  if (idx < tail) {
    Tensor mX = make_tensor(make_gmem_ptr(X + offset), make_shape(tail));
    Tensor mY = make_tensor(make_gmem_ptr(Y + offset), make_shape(tail));
    mY(idx) = sigmoidf_(mX(idx));
  }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t numel = x_c.numel();
  if (numel == 0) return y;

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  constexpr int Vec = 4;
  constexpr int Threads = 128;

  int64_t numel_vec = numel / Vec;
  int64_t tail = numel - numel_vec * Vec;

  bool handled_all_scalar = false;
  if (numel_vec > 0) {
    const bool vec_aligned =
        ((reinterpret_cast<size_t>(x_ptr) & 0xF) == 0) &&
        ((reinterpret_cast<size_t>(y_ptr) & 0xF) == 0);
    if (vec_aligned) {
      // Cap grid size; kernel uses a grid-stride loop.
      int64_t blocks = (numel_vec + (int64_t)Threads * 4 - 1) / ((int64_t)Threads * 4);
      if (blocks > 65535) blocks = 65535;
      sigmoid_kernel_vec<Vec><<<(unsigned)blocks, Threads, 0, stream>>>(
          x_ptr, y_ptr, numel_vec);
    } else {
      int64_t blocks = (numel + Threads - 1) / Threads;
      sigmoid_kernel_tail<<<(unsigned)blocks, Threads, 0, stream>>>(
          x_ptr, y_ptr, 0, numel);
      handled_all_scalar = true;
    }
  }
  if (!handled_all_scalar && tail > 0) {
    int64_t blocks = (tail + Threads - 1) / Threads;
    sigmoid_kernel_tail<<<(unsigned)blocks, Threads, 0, stream>>>(
        x_ptr, y_ptr, numel_vec * Vec, tail);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sigmoid kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=sigmoid_cpp_decl,
    cuda_sources=sigmoid_cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Sigmoid activation implemented with a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

